const crypto = require('crypto');
const input = $input.first().json;
const headers = Object.fromEntries(Object.entries(input.headers ?? {}).map(([k,v]) => [k.toLowerCase(), String(v)]));
const tenantId = headers['x-tenant-id'];
const eventId = headers['x-event-id'];
const timestamp = headers['x-timestamp'];
const signature = (headers['x-signature'] ?? '').toLowerCase();
const rawBody = typeof input.rawBody === 'string' ? input.rawBody : JSON.stringify(input.body ?? {});
const fail = (statusCode, error) => [{ json: { valid: false, statusCode, response: { ok: false, error } } }];
if (Buffer.byteLength(rawBody, 'utf8') > 262144) return fail(413, 'payload_too_large');
if (!tenantId || !eventId || !timestamp || !signature) return fail(400, 'missing_headers');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(tenantId) || !uuid.test(eventId)) return fail(400, 'invalid_identifiers');
const ts = Number(timestamp);
if (!Number.isFinite(ts) || Math.abs(Math.floor(Date.now()/1000)-ts) > 300) return fail(401, 'expired_timestamp');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) return fail(503, 'webhook_secret_not_configured');
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${eventId}.${rawBody}`).digest('hex');
const a = Buffer.from(expected, 'hex');
const b = /^[0-9a-f]{64}$/.test(signature) ? Buffer.from(signature, 'hex') : Buffer.alloc(0);
if (a.length !== b.length || !crypto.timingSafeEqual(a,b)) return fail(401, 'invalid_signature');
let payload;
try { payload = JSON.parse(rawBody); } catch { return fail(400, 'invalid_json'); }
if (payload.tenant_id !== tenantId || payload.event_id !== eventId || typeof payload.event_type !== 'string') return fail(400, 'invalid_event');
return [{ json: { valid: true, statusCode: 202, tenant_id: tenantId, event_id: eventId, event_type: payload.event_type, payload } }];

const e = $json;
const accessEvent = e.event_type === 'whatsapp.access.approved' || e.event_type === 'whatsapp.access.rejected';
return [{ json: {
  statusCode: 202,
  response: { ok: true, accepted: true, event_id: e.event_id },
  monitor: { tenant_id: e.tenant_id, event_id: e.event_id, event_type: e.event_type, access_event: accessEvent, received_at: new Date().toISOString() },
  payload: e.payload,
} }];
